"""Builds the RED FLAGS legal pages (EN + UK) for GitHub Pages.

Run: python build.py   (writes index.html, privacy.html, terms.html and uk/)
"""
from pathlib import Path

PUBLISHER = 'Tetiana Lahotska'
EMAIL = 'codexxdev77@gmail.com'
UPDATED_EN = '10 October 2026'
UPDATED_UK = '10 жовтня 2026 року'

CSS = """
:root { --bg:#fbf5f2; --card:#ffffff; --text:#2e2b30; --muted:#6f6a73; --accent:#7a3345; --line:#eadfdb; }
@media (prefers-color-scheme: dark) { :root { --bg:#1d1a1e; --card:#262228; --text:#f3eeee; --muted:#b9b2b8; --accent:#e8a3b1; --line:#3a3439; } }
* { box-sizing:border-box; }
body { margin:0; background:var(--bg); color:var(--text); font:16px/1.6 -apple-system, "Segoe UI", Roboto, sans-serif; }
main { max-width:760px; margin:0 auto; padding:32px 16px 64px; }
header { display:flex; justify-content:space-between; align-items:center; gap:12px; flex-wrap:wrap; margin-bottom:24px; }
.brand { font-family:Georgia, "Times New Roman", serif; font-size:22px; letter-spacing:1px; color:var(--accent); text-decoration:none; }
nav a { color:var(--accent); margin-left:12px; }
h1 { font-family:Georgia, serif; font-weight:normal; font-size:32px; margin:8px 0 4px; }
h2 { font-size:19px; margin:28px 0 8px; }
.updated { color:var(--muted); margin:0 0 20px; }
section { background:var(--card); border:1px solid var(--line); border-radius:16px; padding:4px 20px 16px; margin:14px 0; }
ul { padding-left:20px; }
a { color:var(--accent); }
footer { color:var(--muted); font-size:14px; margin-top:32px; }
"""


def page(lang, title, body, other_href, other_label, home_href, updated_label):
    return f"""<!doctype html>
<html lang="{lang}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title} · RED FLAGS</title>
<style>{CSS}</style>
</head>
<body>
<main>
<header>
  <a class="brand" href="{home_href}">RED FLAGS</a>
  <nav><a href="{other_href}" hreflang="{'uk' if lang == 'en' else 'en'}">{other_label}</a></nav>
</header>
<h1>{title}</h1>
<p class="updated">{updated_label}</p>
{body}
<footer>{PUBLISHER} · <a href="mailto:{EMAIL}">{EMAIL}</a></footer>
</main>
</body>
</html>
"""


def sections(items):
    return '\n'.join(f'<section><h2>{h}</h2>\n{b}\n</section>' for h, b in items)


